  `currency_id` int(11) NOT NULL,
  `account_type` enum('SAVINGS','CHECKING','INVESTMENT','FEE_INCOME','FX_PNL','CLEARING','LOAN_BOOK','DEPOSIT_POOL') DEFAULT 'SAVINGS',
